  this._extensions =
    opts.extensions !==
    undefined
      ? normalizeList(opts.extensions, "extensions option")
      : []

  this._immutable =
    opts.immutable !==
    undefined
      ? Boolean(opts.immutable)
      : false

  this._index =
    opts.index !==
    undefined
      ? normalizeList(opts.index, "index option")
      : ["index.html"]

  this._lastModified =
    opts.lastModified !==
    undefined
      ? Boolean(opts.lastModified)
      : true

  this._maxage =
    opts.maxAge ||
    opts.maxage
  this._maxage =
    typeof this._maxage ===
    "string"
      ? ms(this._maxage)
      : Number(this._maxage)
